class Solution:
    def gameResult(self, moves: List[List[int]]) -> str:
        b = [[""] * 3 for _ in range(3)]
        for i, (r, c) in enumerate(moves):
            b[r][c] = "A" if i % 2 == 0 else "B"
        lines = [[(r, 0), (r, 1), (r, 2)] for r in range(3)]
        lines += [[(0, c), (1, c), (2, c)] for c in range(3)]
        lines += [[(0, 0), (1, 1), (2, 2)], [(0, 2), (1, 1), (2, 0)]]
        for line in lines:
            vals = {b[r][c] for r, c in line}
            if len(vals) == 1 and "" not in vals:
                return vals.pop()
        return "Draw" if len(moves) == 9 else "Pending"

