function gameResult(moves: number[][]): string {
  const rows = [0, 0, 0], cols = [0, 0, 0];
  let diag = 0, anti = 0;
  for (let i = 0; i < moves.length; i++) {
    const [r, c] = moves[i];
    const s = i % 2 === 0 ? 1 : -1;
    rows[r] += s;
    cols[c] += s;
    if (r === c) diag += s;
    if (r + c === 2) anti += s;
    if ([rows[r], cols[c], diag, anti].some(v => Math.abs(v) === 3)) return s === 1 ? "A" : "B";
  }
  return moves.length === 9 ? "Draw" : "Pending";
}

